@startuml

class Client {
  + NIN
  + TIN
  + Name
  + Address
}

class Reservation {
  + Pickup_Day
}

class Return {
  + Return_Day
}

class Store {
  + Name
  + Address
}

class BicycleModel {
  + Name
  + Type
  + No_Gears
}

class Bicycle {
  + Number
}

Client "1" -- "*" Reservation : makes
Reservation "*" -- "1" Store : at
Reservation "*" -- "1" BicycleModel : for
Reservation "0..1" -- "1" Bicycle : when picked up
Return "*" -- "1" Bicycle : involves

@enduml

